insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (214, 2, 2, null, 'Fridge temperature', 'food_safety', 'base', 'data_photo', true, false, null, null, 8.0, 'celsius', 'fridge_temp', true, true, 'Legal max 8°C [LAW]; FSA target 5°C [FSA]. Move stock to a working fridge and contact management immediately if exceeded.', 1, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Read the fridge''s display or probe an item. Record the number. Photo the display. Flag if above 8°C.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (215, 3, 2, null, 'Freezer temperature', 'food_safety', 'base', 'data_photo', true, false, null, null, -18.0, 'celsius', 'freezer_temp', true, true, 'FSA standard: freezer should read -18°C or below [FSA]. Check door seal and consider moving stock if above.', 2, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Read the display, record the number, photo it. Flag if warmer than -18°C.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (216, 4, 2, null, 'Walk-in cold room temperature', 'food_safety', 'base', 'data_photo', true, false, null, null, 8.0, 'celsius', 'fridge_temp', true, true, 'Legal max 8°C [LAW]; FSA target 5°C [FSA]. Move stock to a working unit and contact management immediately if exceeded.', 5, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Read the wall thermometer, record it, photo it. Flag if above 8°C.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (217, 5, 2, null, 'Blast chiller cycle temperature', 'food_safety', 'base', 'data', false, false, null, null, null, null, null, false, false, 'Part of the cooked-to-chilled cooling process - see the Cooling log task for the 90-minute rule [FSA].', 4, '2026-10-17T08:36:33.000Z', null, 'high', 'chefCook', 'Record start and end temperature of the cycle. Food should go from 70°C to below 3°C within 90 minutes.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (218, 6, 2, null, 'Display/serve-over fridge temperature', 'food_safety', 'base', 'data_photo', true, false, null, null, 8.0, 'celsius', 'fridge_temp', true, true, 'Legal max 8°C [LAW]; FSA target 5°C [FSA]. Move stock to a working fridge and contact management immediately if exceeded.', 21, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Check the chilled display holding food for service. Record the reading, photo it. Must stay at or below 8°C.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (219, 7, 2, null, 'Cooked food core temperature', 'food_safety', 'base', 'data_photo', true, false, null, 70.0, null, 'celsius', 'cooked_core_temp', true, true, 'Core must reach 70°C for 2 min, or equivalent e.g. 75°C for 30s [FSA]. Scotland: 75°C/30s required by law for high-risk foods [LAW]. This app records a single reading, not time-at-temperature - use a calibrated probe and confirm the hold time manually.', null, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Probe the thickest part of the food. Record the number, photo it. Must reach 70°C for 2 min (or 75°C). Beef/lamb whole cuts (steaks, joints) can be served rare if fully seared outside - pork and rolled joints must never be rare. Fish: cook through in the centre - some fish (e.g. tuna) may be served rare only if correctly frozen beforehand and fully seared outside. Liver/offal (pate, parfait): must reach a safe temperature in the centre, not just be seared. Eggs: cook until steaming hot, unless using pasteurised egg or a British Lion/equivalent assured scheme for a lightly-cooked dish.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (220, 8, 2, null, 'Reheated food core temperature', 'food_safety', 'base', 'data_photo', true, false, null, 70.0, null, 'celsius', 'reheated_core_temp', true, true, 'England/Wales/NI: reheat to approximately 70°C for 2 min [FSA]. Scotland: 82°C required by law [LAW]. This app records a single reading, not time-at-temperature.', null, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Probe the centre of the reheated item. Record it, photo it. Must be piping hot throughout (~70°C; Scotland 82°C).', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (221, 9, 2, null, 'Hot-holding temperature', 'food_safety', 'base', 'data_photo', true, false, null, 63.0, null, 'celsius', 'hot_hold_temp', true, true, 'Must hold at 63°C or above [LAW]. Below 63°C, a single 2-hour time-control window applies before food must be discarded or used.', 14, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Probe food held hot for service. Record it, photo it. Must stay at or above 63°C.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (222, 10, 2, null, 'Cooling log (cooked to chilled)', 'food_safety', 'base', 'data_tick', false, false, null, null, 8.0, 'celsius', 'cooling_temp', true, true, 'Must cool from cooked to below 8°C within 90 minutes [FSA] (the ''90-minute rule'').', null, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Note the time cooking finished and the time it reached fridge-cold. Must be below 8°C within 90 minutes.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (223, 11, 2, null, 'Reheat-once verification', 'food_safety', 'base', 'tick', false, false, null, null, null, null, null, false, false, '[FSA] guidance: reheat food once only - do not reheat leftovers a second time.', null, '2026-10-17T08:36:33.000Z', null, 'high', 'chefCook', 'Confirm this item hasn''t been reheated before. Food may only be reheated once, then discarded.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (224, 12, 2, null, 'Probe calibration check', 'food_safety', 'base', 'data_tick', false, false, null, null, null, null, null, false, false, '[BEST] Check probe reads 0°C in melting ice and 100°C in boiling water, both within ±1°C. No UK legal figure - an industry best-practice calibration check.', null, '2026-10-17T08:36:33.000Z', null, 'high', 'chefCook', 'Test the probe in iced water (should read ~0°C) and boiling water (~100°C). Record both. Flag if off by more than 1°C.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (225, 13, 2, null, 'Probe sanitised between uses', 'food_safety', 'base', 'tick', false, false, null, null, null, null, null, false, false, null, null, '2026-10-17T08:36:33.000Z', null, 'high', 'chefCook', 'Wipe the probe with a sanitiser wipe before and after each use.', false, null, null, false) on conflict (id) do nothing;
insert into task_templates (id, template_group_id, version_number, previous_version_id, title, segment, applicable_role_tiers, method, requires_photo, requires_notes, custom_fields_json, min_limit, max_limit, unit, legal_limit_category, is_critical, requires_corrective_action_on_fail, fix_instructions, equipment_type_id, created_at, created_by_user_id, priority, job_role, guidance_text, requires_supplier_selection, organisation_id, extra_fields_json, random_photo_check_enabled) values (226, 14, 2, null, 'Use-by / best-before date check', 'food_safety', 'base', 'tick_note', false, true, null, null, null, null, null, true, true, null, null, '2026-10-17T08:36:33.000Z', null, 'critical', 'chefCook', 'Check opened and stored items for their dates. Note and remove anything past its use-by date.', false, null, null, false) on conflict (id) do nothing;
